-- Nexmark q19 on clink, BLACKHOLE sink variant. Local bid ranking: the top 10
-- bids per auction by price. Ranked state per key, retracting as higher bids
-- arrive.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='nx-bid',
        group_id='clink-q19bh-bid', auto_offset_reset='earliest',
        event_time_column='datetime', watermark_lag_ms='4000');
CREATE TABLE sink_q19 (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT) WITH (connector='blackhole');
INSERT INTO sink_q19
SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY auction ORDER BY price DESC, datetime DESC, bidder DESC) AS rn FROM bid) AS R WHERE rn <= 10;
